dtsPropsFor.Tabs:
/** Tab buttons in order; ids are also used to build element ids. */
tabs: ReadonlyArray<{ id: string; label: string }>;
/** Id of the selected tab (controlled). */
active: string;
/** Called with the newly selected tab id (click, ArrowLeft/ArrowRight, Home/End). */
onChange: (id: string) => void;
/** Accessible name for the tab list. */
label: string;
/** Prefix for `${idPrefix}-tab-${id}` and the `${idPrefix}-panel-${id}` it controls; pass the same value to each TabPanel. */
idPrefix: string;
/** Class for the tablist element; use "query-tabs" for the site's underlined tab style. */
className?: string;

dtsPropsFor.TabPanel:
/** This panel's tab id. */
id: string;
/** Id of the selected tab; the panel is hidden (but stays mounted) when it differs from id. */
active: string;
/** Same idPrefix as the paired Tabs. */
idPrefix: string;
/** Panel content. */
children: React.ReactNode;
className?: string;

dtsPropsFor.Callout:
/** Bold heading line. */
title: string;
/** Body content, usually one or more <p> or a <ul>. */
children: React.ReactNode;
/** Accent (default) or amber warning styling. */
tone?: "info" | "warning";

dtsPropsFor.Header:
/** Which section is current: "site" for query.host pages, "docs" for documentation. */
active: "docs" | "site";
/** Request hostname; "query.host" or "docs.query.host" produce canonical links, anything else uses same-origin paths. */
hostname: string;
/** Brand mark image URL; defaults to the QueryHost icon. */
iconSrc?: string;

dtsPropsFor.PolicyLayout:
/** Page title rendered as the h1. */
title: string;
/** Policy body: h2 sections, paragraphs, and lists. */
children: React.ReactNode;
/** Request hostname passed to Header (e.g. "query.host"). */
hostname: string;

dtsPropsFor.DocsLayout:
/** Href of the current page in the docs navigation, e.g. "/querying/" (trailing slash; "/" is Getting started). */
activeHref: string;
/** Page h1. */
title: string;
/** Lead paragraph under the title. */
description: string;
/** Small uppercase accent kicker above the title. */
eyebrow?: string;
/** Widen the content column for tables. */
wide?: boolean;
/** Reserve the wide-screen "On this page" column; set it for pages with several h2 sections. */
contents?: boolean;
/** Request hostname, e.g. "docs.query.host". */
hostname: string;
/** Extra sidebar list shown under Reference while inside the API reference. */
reference?: { label: string; items: ReadonlyArray<{ href: string; label: string }> };
/** Page body, styled by .doc-prose. Pass children OR html, not both. */
children?: React.ReactNode;
/** Trusted pre-rendered HTML body, used instead of children. */
html?: string;

dtsPropsFor.DocsSidebar:
/** Href of the current page, e.g. "/querying/"; that link is highlighted. */
activeHref: string;
/** Request hostname, e.g. "docs.query.host". */
hostname: string;
/** Extra list shown under the Reference section. */
reference?: { label: string; items: ReadonlyArray<{ href: string; label: string }> };
/** Navigation sections; defaults to the QueryHost documentation tree. */
sections?: ReadonlyArray<{ label: string; items: ReadonlyArray<{ href: string; label: string }> }>;

dtsPropsFor.DocsMobileNavigation:
/** Href of the current page, e.g. "/querying/". Visible only below 50rem viewport width. */
activeHref: string;
/** Request hostname, e.g. "docs.query.host". */
hostname: string;
/** Extra reference links appended to the menu. */
reference?: { label: string; items: ReadonlyArray<{ href: string; label: string }> };
/** Navigation sections; defaults to the QueryHost documentation tree. */
sections?: ReadonlyArray<{ label: string; items: ReadonlyArray<{ href: string; label: string }> }>;

dtsPropsFor.CustomSelect:
/** Unique id; also prefixes the label, value, and menu ids. */
id: string;
/** Visible field label. */
label: string;
/** Form field name for the hidden native select. */
name: string;
/** Options; value must match one option's value or the component throws. */
options: ReadonlyArray<{ label: string; value: string }>;
/** Currently selected value (controlled). */
value: string;
/** Called with the newly selected value. */
onChange: (value: string) => void;
/** Small help text under the control. */
help?: string;
/** Accessible name and placeholder for a type-to-filter box at the top of the menu; omit for short lists. */
filterLabel?: string;
required?: boolean;

dtsPropsFor.QueryPlayground:
/** Games offered in the Game select; form defaults come from the selected game. */
games: ReadonlyArray<{ id: string; name: string; defaultMode: "full" | "summary"; defaultPort?: number; defaultQueryPort?: number; queryPortStrategy?: "offset" | "fixed"; capabilities: Record<"summary" | "players" | "rules" | "mods" | "plugins" | "resources" | "srv", "supported" | "conditional" | "unsupported"> }>;
/** URL query string that prefills the form, e.g. "?game=rust&host=play.example.com&port=28015"; "" for a blank form. Submitting POSTs to /api/query. */
search: string;

dtsPropsFor.QueryResult:
/** Game list used to show the game's display name (same shape as QueryPlayground games). */
games: ReadonlyArray<{ id: string; name: string; defaultMode: "full" | "summary"; defaultPort?: number; capabilities: Record<string, "supported" | "conditional" | "unsupported"> }>;
/** Hosted query response; the JSON tab shows it pretty-printed. ok:true -> server + data; ok:false -> error. */
result:
  | { ok: true; game: string; durationMs: number; partial: boolean; cache: { status: "hit" | "miss" | "coalesced"; ageMs: number; ttlMs: number }; server: { name?: string; map?: string; version?: string; players?: { online: number; max: number }; password?: boolean; queryRttMs?: number }; data: Record<string, unknown>; rawData?: Record<string, unknown>; sources: ReadonlyArray<{ source: string; status: "ok" | "timeout" | "failed" | "blocked" | "malformed" | "unsupported" | "not-requested"; rttMs?: number }>; warnings: ReadonlyArray<{ code: string; message: string; source?: string }> }
  | { ok: false; game: string; durationMs: number; cache: { status: "hit" | "miss" | "coalesced"; ageMs: number; ttlMs: number }; error: { code: string; message: string; source?: string }; sources: ReadonlyArray<{ source: string; status: string; rttMs?: number }>; warnings: ReadonlyArray<{ code: string; message: string }> };
